// Merge K Sorted Lists concept using Min Heap
var heap = AnimatedHeap<Int>(kind: .min)
let lists = [[1, 4], [2, 6], [0, 9]]

for list in lists {
    for val in list {
        heap.insert(val)
    }
}

var mergedList: [Int] = []
while !heap.isEmpty {
    if let val = heap.extract() {
        mergedList.append(val)
    }
}
